### Contoh

Arah import sebaiknya **satu jalur**: `main.js` mengimpor fitur, fitur mengimpor `lib`, dan `lib` tidak mengimpor fitur. Import melingkar (A mengimpor B, B mengimpor A) membuat urutan pemuatan membingungkan dan bisa menghasilkan nilai yang belum siap.

Satu file `config.js` yang membaca semua variabel lingkungan membuat pengaturan mudah ditemukan:

```js
// src/config.js
export const config = {
  port: Number(process.env.PORT ?? 3000),
  pajak: Number(process.env.PAJAK ?? 11),
};
```

File lain cukup `import { config } from '../config.js'`, tidak membaca `process.env` sendiri-sendiri.

cards.code:
// === src/config.js ===
export const config = { pajak: Number(process.env.PAJAK ?? 11) };
// === src/lib/uang.js ===
export const rupiah = (n) => 'Rp' + n.toLocaleString('id-ID');
// === src/produk/produk.data.js ===
export const PRODUK = [
  { nama: 'Kopi Susu', harga: 18000 },
  { nama: 'Teh Tarik', harga: 12000 },
];
// === src/produk/produk.layanan.js ===
import { PRODUK } from './produk.data.js';
import { config } from '../config.js';
export function hargaAkhir(nama) {
  const p = PRODUK.find((x) => x.nama === nama);
  return Math.round(p.harga * (1 + config.pajak / 100));
}
// === src/produk/index.js ===
export { hargaAkhir } from './produk.layanan.js';
// === main.js ===
import { hargaAkhir } from './src/produk/index.js';
import { rupiah } from './src/lib/uang.js';
console.log(rupiah(hargaAkhir('Kopi Susu')));
console.log(rupiah(hargaAkhir('Teh Tarik')));

